    let y = x * 2;
    let z = y + 3;
    return z;
}

fn sum3(a: i32, b: i32, c: i32) -> i32 {
    let sum_ab = a + b;
    let total = sum_ab + c;
    return total;
}

fn settle(m: Meter) -> i32 {
    let kept = m;
    return kept.level + kept.level;
}

fn main() -> i32 {
    let mut meter = Meter { level: 5 };
    if (boost(&mut meter, 3) != 10) {
        return 1;
    }
    return 0;
}
